using System;
using UnityEngine;
namespace Yamyam.RigidTeaching {
 public sealed partial class RigidDynamicsStage {
  readonly System.Collections.Generic.List<GameObject> demonstrators=new System.Collections.Generic.List<GameObject>();
  Vector3 Center=>new Vector3(-4.7f,.2f,0);
  void Arc(Vector3 c,float r,double end,Color color){var points=new Vector3[49];for(int i=0;i<points.Length;i++){double a=end*i/(points.Length-1);points[i]=c+new Vector3((float)Math.Cos(a),(float)Math.Sin(a))*r;}Path(color,points);}
  void Coil(Vector3 a,Vector3 b,Color color){var pts=new Vector3[65];Vector3 d=b-a,side=Vector3.Cross(d.normalized,Vector3.forward)*.16f;for(int i=0;i<pts.Length;i++){float t=i/(float)(pts.Length-1);pts[i]=a+d*t+side*Mathf.Sin(t*16*Mathf.PI);}Path(color,pts);}
  void Axes(Vector3 c,DQuaternion q,float size=1.3f){D3[] basis={new D3(1,0,0),new D3(0,1,0),new D3(0,0,1)};Color[] colors={Red,Teal,Blue};for(int i=0;i<3;i++){Vector3 b=c+Spatial(q.Rotate(basis[i]))*size;Arrow(c,b,colors[i]);}}
  // Fixed oblique projection for the explicitly labelled mathematical diagrams.
  Vector3 Spatial(D3 v)=>new Vector3((float)(v.x+.35*v.z),(float)(v.y+.25*v.z),0);
  void RigidPicture(double u){switch(shot.picture){
   case DynamicsPicture.AngularVelocity:AngularVelocity(u);break;case DynamicsPicture.TangentialForce:TangentialForce(u);break;case DynamicsPicture.TorqueLever:DoorTorque(u);break;case DynamicsPicture.Couple:ForceCouple(u);break;
   case DynamicsPicture.TensorAxes:TensorAxes(u);break;case DynamicsPicture.TensorExpansion:TensorExpansion(u);break;case DynamicsPicture.GyroscopicTerm:GyroscopicTerm(u);break;case DynamicsPicture.ParallelAxis:ParallelAxis(u);break;
   case DynamicsPicture.PointVelocity:PointVelocity(u);break;case DynamicsPicture.WorldInertia:WorldInertia(u);break;case DynamicsPicture.EngineComponents:EngineDiagram(u,0);break;case DynamicsPicture.BodyState:EngineDiagram(u,1);break;case DynamicsPicture.Accumulators:EngineDiagram(u,2);break;case DynamicsPicture.CollisionShapes:EngineDiagram(u,3);break;
   case DynamicsPicture.Joints:JointMotion(u);break;case DynamicsPicture.Motor:MotorMotion(u);break;case DynamicsPicture.GameLoop:GameLoop(u);break;case DynamicsPicture.Penalty:Penalty(u);break;case DynamicsPicture.SequentialImpulse:SequentialImpulse(u);break;case DynamicsPicture.ConstraintJacobian:ConstraintJacobian(u);break;
   case DynamicsPicture.ConnectedSprings:ConnectedSprings(u);break;case DynamicsPicture.EulerTangent:EulerTangent(u);break;case DynamicsPicture.IntegratorGraph:IntegratorGraph(u);break;case DynamicsPicture.RotationStep:RotationStep(u);break;
   case DynamicsPicture.FanSail:FanSail(u);break;case DynamicsPicture.TugOfWar:TugOfWar(u);break;case DynamicsPicture.FreeFallOrbit:FreeFallOrbit(u);break;case DynamicsPicture.Incline:Incline(u);break;case DynamicsPicture.HangingSpring:HangingSpring(u);break;case DynamicsPicture.Oscillator:Oscillator(u);break;
   case DynamicsPicture.WalkingCarriage:WalkingCarriage(u);break;case DynamicsPicture.VehicleRestitution:VehicleRestitution(u);break;case DynamicsPicture.Balance:Balance(u);break;case DynamicsPicture.CylinderInertia:CylinderInertia(u);break;case DynamicsPicture.StudyLinks:StudyLinks(u);break;case DynamicsPicture.TotalSummary:TotalSummary(u);break;
   default:throw new ArgumentOutOfRangeException();}}
  void AngularVelocity(double u){var c=Center;double a=shot.angularSpeed*u*2.4;float r1=.9f,r2=2;Circle(c,r1,Muted);Circle(c,r2,Muted);Vector3 d=new Vector3((float)Math.Cos(a),(float)Math.Sin(a)),t=new Vector3(-d.y,d.x);Dot(c,.12f,Yellow);Dot(c+d*r1,.18f,Blue);Dot(c+d*r2,.22f,Teal);Arrow(c+d*r1,c+d*r1+t*r1*.6f,Blue);Arrow(c+d*r2,c+d*r2+t*r2*.6f,Teal);Path(White,c,c+d*r2);Tag(new Vector3(-7,3),"같은 각속도 · 다른 선속력",Yellow,950);formula.text="ω = 각속도 (rad/s)\nv = ω × r\n\n|v| = |ω| r⊥\n축 위에서는 r⊥ = 0";values.text="각 점의 원 중심은 회전축 위 가장 가까운 점 · 평면 단면";}
  void TangentialForce(double u){var c=Center;double a=shot.forceAngle*Math.PI/180;Vector3 radial=Vector3.right,tangent=Vector3.up,p=c+radial*1.7f,F=new Vector3((float)Math.Cos(a),(float)Math.Sin(a))*2;Circle(c,1.7f,Muted);Dot(c,.1f,Yellow);Dot(p,.3f,Blue);Path(White,c,p);Arrow(p,p+F,Red);Arrow(p,p+Vector3.up*F.y,Teal);Arrow(p,p+Vector3.right*F.x,Yellow);formula.text="F⊥ = F sinθ\naₜ = F⊥/m\nα = aₜ/r\n\n구심 가속도: v²/r (안쪽)";values.text="접선 성분은 회전율 변화 · 구심 성분은 궤도 방향 변화";}
  void DoorTorque(double u){var hinge=new Vector3(-6,-1.1f);Vector3 radial=new Vector3((float)Math.Cos(u*.6),(float)Math.Sin(u*.6));float r=(float)Math.Min(3.8,shot.leverArm);Path(White,hinge,hinge+radial*3.8f);Dot(hinge,.18f,Muted);Dot(hinge+radial*r,.16f,Yellow);Vector3 force=Quaternion.Euler(0,0,(float)shot.forceAngle)*radial;Arrow(hinge+radial*r,hinge+radial*r+force*1.6f,Red);Tag(new Vector3(-7,3),"경첩에서 힘을 가하는 곳까지",Yellow,950);formula.text="τ = r × F\n|τ| = rF sinθ\n\nr = "+N(r)+" m\nθ = "+N(shot.forceAngle)+"°\nτ = "+N(r*shot.torqueForce*Math.Sin(shot.forceAngle*Math.PI/180))+" N·m";values.text="문을 위에서 본 단면 · 힘의 크기는 동일";}
  void ForceCouple(double u){var c=Center;Crate(c);if(shot.spokenStep==0){Arrow(c-Vector3.right*2,c,Red);Cross(c,Yellow);formula.text="작용선이 질량중심 통과\n알짜힘 ≠ 0\n질량중심 주위 τ = 0";}else{Arrow(c+Vector3.up*.65f,c+new Vector3(-2,.65f),Red);Arrow(c+Vector3.down*.65f,c+new Vector3(2,-.65f),Blue);Arc(c,1.7f,u*2,Yellow);formula.text="같은 크기 · 반대 방향 · 다른 작용선\nΣF = 0\nΣτ ≠ 0\n\n우력 (Couple)";}values.text="힘의 합과 토크의 합은 서로 다른 정보";}
  void TensorAxes(double u){var c=Center;Vector3 axis=shot.spokenStep==0?Vector3.up:Vector3.right;Vector3 d=shot.spokenStep==0?Vector3.up:new Vector3((float)Math.Cos(u*2),(float)Math.Sin(u*2));Path(White,c-d*2,c+d*2);Dot(c,.15f,Yellow);Arrow(c-axis*2.5f,c+axis*2.5f,Teal);for(int i=-2;i<=2;i++)Dot(c+d*i,.16f,Blue);formula.text="L = I ω\n\n길이축으로 회전: 작은 관성\n가로축으로 회전: 큰 관성\n\nI는 대칭행렬 · 회전행렬과 구별";values.text="같은 막대의 질량 분포를 두 축에서 비교";}
  void TensorExpansion(double u){D3 r=new D3(1,2,1),w=new D3(0,0,1),v=D3.Cross(w,r),L=D3.Cross(r,v);var c=Center;Arrow(c,c+Spatial(r),Yellow);Arrow(c+Spatial(r),c+Spatial(r)+Spatial(v)*.55f,Teal);Dot(c+Spatial(r),.2f,Blue);formula.text="v = ω × r\nL = r × (mv)\n\nIx = m(y²+z²)\nIxy = −mxy\nIxz = −mxz\n\nI ω = "+V(L);values.text="m=1, r=(1,2,1), ω=(0,0,1)의 직접 계산";}
  void GyroscopicTerm(double u){DMatrix I=DMatrix.Diagonal(1,2,3);D3 w=new D3(1,1,1),L=I*w,cross=D3.Cross(w,L),alpha=Dynamics.AngularAcceleration(I,w,new D3());var c=Center;Arrow(c,c+Spatial(w),Teal);Arrow(c,c+Spatial(L)*.7f,Yellow);Arrow(c,c+Spatial(alpha),Red);formula.text="τ = Iα + ω × (Iω)\nτ=0일 때\nα = −I⁻¹[ω × (Iω)]\n\nI=diag(1,2,3), ω=(1,1,1)\nα="+V(alpha);values.text="한 순간의 계산 · 청록 ω, 노랑 L, 빨강 α · 일반적으로 평행하지 않음";}
  void ParallelAxis(double u){var c=Center;Dot(c,.75f,Blue);Vector3 shifted=c+Vector3.right*(float)Math.Min(1,2*u);Path(Yellow,c+Vector3.down*2,c+Vector3.up*2);Path(Teal,shifted+Vector3.down*2,shifted+Vector3.up*2);Arrow(c,shifted,White);double d=Math.Min(1,2*u);formula.text="Inew = Icm + m d²\n\n= 0.2 + 2 × "+N(d)+"²\n= "+N(.2+2*d*d)+" kg·m²\n\n3D: Inew=Icm+m[(d·d)E−ddᵀ]";values.text="질량 분포는 그대로 · 평행한 기준축만 이동";}
  void PointVelocity(double u){var c=Center;D3 r=new D3(0,2),w=new D3(0,0,1),vcm=new D3(shot.velocityA,0),v=vcm+D3.Cross(w,r);Path(White,c-Vector3.up*2,c+Vector3.up*2);Dot(c,.13f,Yellow);Dot(c+Vector3.up*2,.18f,Blue);Arrow(c,c+Spatial(vcm)*.7f,Yellow);Arrow(c+Vector3.up*2,c+Vector3.up*2+Spatial(v)*.7f,Teal);formula.text="vcontact = vcm + ω × r\n\nvcm = "+V(vcm)+"\nω × r = (−2,0,0)\nvcontact = "+V(v);values.text="질량중심의 속도와 접촉점 속도를 구별";}
  void WorldInertia(double u){var c=Center;var q=DQuaternion.AxisAngle(new D3(0,0,1),u*Math.PI/2);DMatrix I=DMatrix.Diagonal(1,3,5),W=Dynamics.WorldInertia(I,q);Axes(c,q,2);formula.text="열벡터 관례\nIworld = R Ibody Rᵀ\n\n몸체 I = diag(1,3,5)\n월드 Ixx = "+N(W.c0.x)+"\n월드 Ixy = "+N(W.c1.x);values.text="몸체에 저장한 관성은 고정 · 월드 성분은 자세와 함께 변화";}
  void EngineDiagram(double u,int mode){var c=Center;Crate(c);if(mode==0||mode==3){Path(Teal,c+new Vector3(-.8f,-.8f),c+new Vector3(.8f,-.8f),c+new Vector3(.8f,.8f),c+new Vector3(-.8f,.8f),c+new Vector3(-.8f,-.8f));Tag(new Vector3(-7,3),"그래픽 모델 + 충돌 형상",Teal,950);Arrow(c+Vector3.right, new Vector3(.1f,1.7f),Yellow);}else{Arrow(c,c+Vector3.right*(float)(.5+u),Teal);Arc(c,1.2f,u*1.2,Yellow);}string[] text={"Body: 위치·자세·속도\nShape: 닿는 모양\nConstraint: 유지할 관계","생성 시: m, Ibody, 중심 오프셋\n상태: x, q, v, ω\n유도값: R, invMass, Iworld⁻¹","단계 시작: ΣF=0, Στ=0\n각 원인의 기여를 더함\n힘·토크 ≠ 지속 상태","구·상자·볼록체·삼각형 메시\n오목체 → 볼록 조각\n같은 바디 내부 형상은 합쳐서 처리"};formula.text=text[mode];values.text="청록 경계는 교육용 충돌 형상 · 실제 게임의 내부 데이터가 아님";}
  void JointMotion(double u){var c=Center;int kind=shot.spokenStep;Dot(c,.2f,Yellow);Vector3 p;string name;if(kind==2){p=c+Vector3.right*(float)(-1+2*u);Path(Muted,c+Vector3.left*2,c+Vector3.right*2);name="프리즘 · 축 방향 이동";}else{float a=(float)(u*2-1);p=c+new Vector3(Mathf.Cos(a),Mathf.Sin(a))*1.7f;Path(White,c,p);Arc(c,1.7f,2,Muted);name=kind==0?"볼 소켓 · 위치 구속 / 회전 허용":kind==1?"힌지 · 한 회전축 허용":kind==3?"원통형 · 축 이동 + 축 회전":"유니버설 · 직교하는 두 회전축";}Dot(p,.3f,Blue);if(kind==0||kind>=3)Axes(p,DQuaternion.AxisAngle(new D3(1,1,0),u),.75f);Tag(new Vector3(-7,3),name,Yellow,1000);formula.text="남겨 두는 자유도를 확인\n\n위치 3 + 회전 3\n관절별로 일부를 제한\n\n표시 궤도는 교육용 구속 모형";values.text="이름뿐 아니라 가능한 움직임과 금지한 움직임으로 비교";}
  void MotorMotion(double u){var c=Center;double omega=2*(1-Math.Exp(-3*u)),angle=2*(u-(1-Math.Exp(-3*u))/3);Circle(c,1.8f,Muted);Vector3 p=c+new Vector3((float)Math.Cos(angle),(float)Math.Sin(angle))*1.8f;Path(White,c,p);Dot(p,.23f,Blue);Arrow(p,p+new Vector3(-(p.y-c.y),p.x-c.x)*.5f,Red);formula.text="목표 ωtarget = 2 rad/s\n현재 ω = "+N(omega)+"\n\n|τmotor| ≤ τmax\n목표와의 차이에 반응";values.text="포화가 있는 모터 원리 설명 · 실제 엔진의 모터 측정값은 아님";}
  void GameLoop(double u){string[] labels={"입력·목표·운동학 상태","힘/토크 누적 + 제약 해결","새 위치·자세·충돌 결과","카메라 갱신 → 화면"};int index=Math.Min(3,(int)(u*4));for(int i=0;i<4;i++){var p=new Vector3(-7,2.8f-i*1.35f);Tag(p,labels[i],i==index?Yellow:White,950);if(i<3)Arrow(p+new Vector3(.3f,-.5f),p+new Vector3(.3f,-.95f),Teal);}formula.text="물리 전: 입력 준비\n물리 중: 상태 갱신\n물리 후: 결과 사용\n\n내부 반복 ≠ 새 게임 프레임";values.text="한 단계에서 입력과 결과가 흐르는 방향";}
  void Penalty(double u){double m=1,g=9.8,k=100,depth=m*g/k*(1+Math.Exp(-4*u)*Math.Cos(10*u));var floor=new Vector3(-5,-.6f);Path(Muted,floor+Vector3.left*2,floor+Vector3.right*3);var p=floor+Vector3.up*(float)(.55-depth*4);Dot(p,.55f,Blue);Arrow(p,p+Vector3.up*(float)(k*depth*.08),Teal);Arrow(p,p+Vector3.down*.784f,Red);formula.text="Fpenalty = k × 침투 깊이\n정지 평형: k d = mg\n\nm=1, k=100\ndeq = 0.098 m";values.text="감쇠해 평형으로 가는 개념 궤적 · 침투를 힘으로 보정하는 방식";}
  void SequentialImpulse(double u){double[] v={3,0,0};int iterations=Math.Min(6,(int)(u*7));for(int pass=0;pass<iterations;pass++)for(int i=0;i<2;i++)if(v[i]>v[i+1]){double j=(v[i]-v[i+1])*.5;v[i]-=j;v[i+1]+=j;}for(int i=0;i<3;i++){var p=new Vector3(-7+i*2.2f,.4f);Dot(p,.6f,i==0?Blue:Teal);Arrow(p+Vector3.up,p+new Vector3((float)v[i]*.6f,1),Yellow);Tag(p+Vector3.down*1.4f,"v = "+N(v[i]),White,350);}formula.text="같은 질량 3개 · e=0\n접촉 AB → BC 순서 반복\n반복 횟수 = "+iterations+"\n\nΣp = 3 보존\n속도가 서로 가까워짐";values.text="위치를 먼저 옮기지 않고 접촉 속도를 반복 보정하는 작은 구현";}
  void ConstraintJacobian(double u){Vector3 a=new Vector3(-6.7f,.3f),b=new Vector3(-3,.3f);Dot(a,.5f,Blue);Dot(b,.5f,Teal);Path(White,a,b);Arrow(a,a+Vector3.right,Blue);Arrow(b,b+Vector3.left,Teal);formula.text="C = |xB−xA| − L\nĊ = n·(vB−vA) = Jv\n\n접촉: λ ≥ 0\n분리 허용 · 당기는 접촉력 금지";values.text="야코비 행렬은 상태 변화가 제약 변화율로 이어지는 관계";}
  void ConnectedSprings(double u){var points=new Vector3[5];for(int i=0;i<5;i++){points[i]=new Vector3(-7+i*1.4f,(float)(Math.Sin(i*.7+u*3)*.6));Dot(points[i],.2f,Blue);if(i>0)Coil(points[i-1],points[i],Teal);}Path(Muted,new Vector3(-3,-1),new Vector3(0,-1));formula.text="이웃 위치와 속도 → 힘\n힘 → 가속도\n가속도 → 다음 상태\n\n복잡한 시간 함수는 수치 적분";values.text="연결 관계를 설명하는 도식 · 각 노드의 정확해 시뮬레이션은 아님";}
  void EulerTangent(double u){var c=Center;Circle(c,1.8f,Muted);double h=shot.stepSize,a=u*1.5;Vector3 p=c+new Vector3((float)Math.Cos(a),(float)Math.Sin(a))*1.8f,tangent=new Vector3(-(p.y-c.y),p.x-c.x);Vector3 approximate=p+tangent*(float)h,exact=c+new Vector3((float)Math.Cos(a+h),(float)Math.Sin(a+h))*1.8f;Dot(p,.15f,White);Arrow(p,approximate,Red);Dot(approximate,.12f,Red);Dot(exact,.12f,Teal);formula.text="xnew ≈ x + h v\nv = ω × r\n\n빨강: 접선 한 걸음\n청록: 원 위 정확한 회전\nh = "+N(h);values.text="방향이 계속 바뀌므로 일정 각속도라도 점의 속도 벡터는 일정하지 않음";}
  void IntegratorGraph(double u){double h=shot.stepSize,T=3;Integration[] methods={Integration.ExplicitEuler,Integration.SemiImplicitEuler,Integration.RungeKutta4};Color[] colors={Red,Blue,Teal};for(int m=0;m<3;m++){var p=new System.Collections.Generic.List<Vector3>();KinematicState s=new KinematicState(1,0);for(int i=0;i<=T/h*u;i++){p.Add(new Vector3(-7.5f+(float)(i*h/T*7.4),1+(float)s.position*.75f));s=Dynamics.Integrate(s,i*h,h,(t,x,v)=>-4*x,methods[m]);}if(p.Count>1)Path(colors[m],p.ToArray());}formula.text="x″ = −4x\nx(0)=1, v(0)=0\n\n빨강: 명시적 Euler\n파랑: 반암시적 Euler\n청록: RK4\nh = "+N(h);values.text="같은 미분방정식의 실제 수치 결과 · 정확도와 안정성을 함께 비교";}
  void RotationStep(double u){D3 w=new D3(0,0,1);var q=DQuaternion.Identity;var R=DMatrix.Identity;double h=shot.stepSize;int steps=(int)(u*3/h);for(int i=0;i<steps;i++){if(shot.spokenStep==0)R=Dynamics.MatrixEuler(R,w,h);else q=Dynamics.OrientationStep(q,w,h,true,shot.spokenStep==2);}var c=Center;if(shot.spokenStep==0){Arrow(c,c+Spatial(R.c0)*2,Red);Arrow(c,c+Spatial(R.c1)*2,Teal);Arrow(c,c+Spatial(R.c2)*2,Blue);}else Axes(c,q,2);double a=steps*h;Arc(c,2,a,Muted);formula.text=shot.spokenStep==0?"열벡터·월드 ω\nṘ = [ω]× R\nRnew ≈ R + hṘ\n정규직교화 필요":shot.spokenStep==1?"월드 ω: q̇ = ½(0,ω)q\nqnew = normalize(q+hq̇)\n\n정규화 ≠ 시간 근사 오차 제거":"Δθ = |ω|h\nΔq = AxisAngle(ω̂,Δθ)\nqnew = Δq q\n한 단계의 일정 ω에 정확";values.text=shot.spokenStep==0?"직접 적분한 축 길이: "+N(R.c0.Length)+", "+N(R.c1.Length)+" · 1에서 벗어나는 오차":"현재 자세 축 · 회색 원호는 일정 각속도의 기준";}
  void FanSail(double u){var basePoint=new Vector3(-7,-1.2f);Path(White,basePoint,basePoint+new Vector3(.5f,-.35f),basePoint+new Vector3(5.5f,-.35f),basePoint+new Vector3(6,0),basePoint);Vector3 fan=basePoint+new Vector3(1.4f,1.2f),sail=basePoint+new Vector3(4.6f,1.2f);Circle(fan,.7f,Teal);for(int i=0;i<4;i++){float a=(float)(u*5+i*Math.PI/2);Path(Teal,fan,fan+new Vector3(Mathf.Cos(a),Mathf.Sin(a))*.65f);}Path(White,sail+Vector3.down*1.1f,sail+Vector3.up*1.2f);Path(White,sail+Vector3.up*1.2f,sail+new Vector3(1,.2f),sail+Vector3.down*.9f);Arrow(fan,fan+Vector3.left*1.3f,Red);Arrow(sail,sail+Vector3.right*1.3f,Teal);for(int i=0;i<5;i++)Dot(Vector3.Lerp(fan,sail,(float)((u+i*.2)%1)),.045f,Yellow);formula.text="이상적 정면 배치\n공기 운동량을 돛이 모두 회수\nFfan + Fsail = 0\n\n다른 방향으로 나가는 공기는 별도 계산";values.text="배·선풍기·돛과 공기를 포함한 계의 운동량 장부";}
  void Limb(GameObject parent,Vector3 a,Vector3 b,float radius,Color color){var g=Part(parent,PrimitiveType.Capsule,(a+b)*.5f,new Vector3(radius,(b-a).magnitude*.5f,radius),color);g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,(b-a).normalized);}
  void Demonstrator(int index,Vector3 position,bool faceRight){
   while(demonstrators.Count<=index){var g=GO("Own_articulated_demonstrator_"+demonstrators.Count);sourceObjects.Add(g);demonstrators.Add(g);
    Color cloth=new Color(.21f,.4f,.5f),skin=new Color(.75f,.62f,.49f);Part(g,PrimitiveType.Sphere,new Vector3(0,.85f,0),new Vector3(.42f,.5f,.4f),skin);Part(g,PrimitiveType.Capsule,new Vector3(0,.25f,0),new Vector3(.42f,.4f,.32f),cloth);Part(g,PrimitiveType.Sphere,new Vector3(0,-.16f,0),new Vector3(.46f,.3f,.32f),cloth);
    Limb(g,new Vector3(0,.4f,0),new Vector3(.35f,.05f,0),.16f,cloth);Limb(g,new Vector3(.35f,.05f,0),new Vector3(.85f,.13f,0),.14f,skin);Part(g,PrimitiveType.Sphere,new Vector3(.85f,.13f,0),Vector3.one*.19f,skin);
    Limb(g,new Vector3(-.12f,-.2f,0),new Vector3(-.4f,-.65f,0),.2f,cloth);Limb(g,new Vector3(-.4f,-.65f,0),new Vector3(-.48f,-1.05f,0),.18f,cloth);Limb(g,new Vector3(.12f,-.2f,0),new Vector3(.4f,-.65f,0),.2f,cloth);Limb(g,new Vector3(.4f,-.65f,0),new Vector3(.52f,-1.05f,0),.18f,cloth);Part(g,PrimitiveType.Cube,new Vector3(-.38f,-1.1f,0),new Vector3(.4f,.17f,.26f),Muted);Part(g,PrimitiveType.Cube,new Vector3(.62f,-1.1f,0),new Vector3(.4f,.17f,.26f),Muted);
   }
   var person=demonstrators[index];person.SetActive(true);person.transform.position=position;person.transform.localScale=new Vector3(faceRight?1:-1,1,1);
  }
  void TugOfWar(double u){Vector3 a=new Vector3(-6.7f,.2f),b=new Vector3(-2.6f,.2f);Demonstrator(0,a,true);Demonstrator(1,b,false);Path(White,a+new Vector3(.85f,.13f),b+new Vector3(-.85f,.13f));Arrow(a+Vector3.down*.35f,a+new Vector3(1,-.35f),Red);Arrow(b+Vector3.down*.35f,b+new Vector3(-1,-.35f),Red);Arrow(a+Vector3.down*1.35f,a+new Vector3(-1.5f,-1.35f),Teal);Arrow(b+Vector3.down*1.35f,b+new Vector3(1,-1.35f),Teal);formula.text="줄의 힘: 같은 크기·반대 방향\n땅의 정지 마찰: 외력\n\n계 전체의 외력 불균형\n→ 전체 운동량 변화";values.text="우리 관절 인형의 힘 설명 · 빨강 줄, 청록 땅";}
  void FreeFallOrbit(double u){if(shot.spokenStep==0){double y=2-3*u*u;for(int i=0;i<2;i++)Dot(new Vector3(-6.5f+i*3,(float)y),i==0?.2f:.5f,i==0?Blue:Teal);formula.text="F=mg, a=F/m\n→ a=g\n\n공기 저항을 생략한 일정 중력\n질량과 무관하게 같은 낙하";}else{var c=Center;Dot(c,1.2f,Blue);Circle(c,2.1f,Muted);Vector3 p=c+new Vector3((float)Math.Cos(u*2),(float)Math.Sin(u*2))*2.1f;Dot(p,.15f,White);Arrow(p,c+(p-c)*.65f,Red);formula.text="a = v²/r ≈ 8.85 m/s²\n\n정거장과 사람이 함께 자유 낙하\n지지력이 작아 무중량처럼 느낌";}values.text="교육용 길이 축척 · 공기 저항 및 다른 천체 영향 생략";}
  void Incline(double u){double mu=.62,angle=Math.Atan(mu);var c=Center;Vector3 d=new Vector3((float)Math.Cos(angle),(float)Math.Sin(angle));Path(White,c-d*3,c+d*3);Dot(c+new Vector3(-d.y,d.x)*.3f,.3f,Blue);Arrow(c,c+Vector3.down*1.5f,Red);formula.text="mg sinθ ≤ μs mg cosθ\n→ tanθ ≤ μs\n\nθcrit = atan(0.62)\n≈ 31.8°";values.text="같은 계수와 이상적 조건에서 g 약분 · 지구/달 임계각 동일";}
  void HangingSpring(double u){var top=new Vector3(-4.8f,2.6f);double mass=shot.massA,g=shot.force,k=490,stretch=mass*g/k;Vector3 p=top+Vector3.down*(1.3f+(float)stretch*8);Path(White,top+Vector3.left*1.7f,top+Vector3.right*1.7f);Coil(top,p,Teal);Dot(p,.35f,Blue);Arrow(p,p+Vector3.down*.9f,Red);formula.text="평형: kΔx = mg\nk = 490 N/m\n\nm = "+N(mass)+" kg\ng = "+N(g)+" m/s²\nΔx = "+N(stretch)+" m";values.text="용수철 늘어난 길이는 확대해 표시 · 같은 k에서 m 또는 g만 변경";}
  void Oscillator(double u){double k=100,m=5,A=.147,w=Math.Sqrt(k/m),t=2*u,x=A*Math.Cos(w*t),v=-A*w*Math.Sin(w*t);var p=new Vector3(-4.7f+(float)x*12,0);Coil(new Vector3(-8,0),p,Teal);Dot(p,.35f,Blue);Arrow(p+Vector3.down,p+new Vector3((float)v*2,-1),Yellow);formula.text="ω=√(k/m)=√20\nf=ω/(2π)≈0.712 Hz\nx=A cos(ωt)\n\nA=0.147 m\nvmax=Aω≈0.657 m/s";values.text="현재 x="+N(x)+" m, v="+N(v)+" m/s · 감쇠 없는 해석해";}
  void WalkingCarriage(double u){double baseV=shot.platformSpeed,t=16*u,vc=baseV-75*1.25/1075,vp=vc+1.25;var start=new Vector3(-7,-.6f);float scale=.25f;Vector3 car=start+Vector3.right*(float)((vc-baseV)*t*scale),person=start+Vector3.right*(float)((vp-baseV)*t*scale);Path(White,car+new Vector3(-.4f,-.4f),car+new Vector3(5.4f,-.4f),car+new Vector3(5.4f,1.4f),car+new Vector3(-.4f,1.4f),car+new Vector3(-.4f,-.4f));Dot(car+new Vector3(.5f,-.7f),.2f,Muted);Dot(car+new Vector3(4.5f,-.7f),.2f,Muted);Dot(person+Vector3.up*.7f,.18f,Blue);Path(Blue,person+Vector3.up*.5f,person+Vector3.down*.1f);formula.text="1000 vc + 75 vp = 1075 v₀\nvp − vc = 1.25\n\nvc = "+N(vc)+" m/s\nvp = "+N(vp)+" m/s\nt = "+N(t)+" s";values.text="카메라 기준속도 v₀="+N(baseV)+" m/s · 계 전체 운동량과 상대 걷기 속도 동시 만족";}
  void VehicleRestitution(double u){D3 va=new D3(-35/3.6,0),vb=new D3(65*Math.Cos(115*Math.PI/180)/3.6,65*Math.Sin(115*Math.PI/180)/3.6),n=new D3(-Math.Sin(20*Math.PI/180),-Math.Cos(20*Math.PI/180));var hit=Dynamics.Resolve(new Body{inverseMass=1.0/1500,velocity=va},new Body{inverseMass=1.0/2500,velocity=vb},new D3(),new D3(),n,.1);var c=Center;Arrow(c,c+Spatial(n)*2,Yellow);Arrow(c,c+Spatial(va)*.15f,Red);Arrow(c,c+Spatial(hit.a.velocity)*.15f,Blue);Arrow(c,c+Spatial(hit.b.velocity)*.15f,Teal);formula.text="계산 전에 km/h → m/s\nJ = "+N(hit.impulseOnB.Length)+" N·s\n\nvA′ = "+V(hit.a.velocity*3.6)+" km/h\nvB′ = "+V(hit.b.velocity*3.6)+" km/h";values.text="노랑 접촉 법선 · 빨강 A 입사 · 파랑 A 결과 · 청록 B 결과";}
  void Balance(double u){var pivot=Center+Vector3.up*.8f;float angle=(float)(.45*Math.Cos(u*6)*Math.Exp(-u));Vector3 d=new Vector3(Mathf.Cos(angle),Mathf.Sin(angle));Vector3 down=new Vector3(d.y,-d.x);Path(White,pivot-d*2,pivot+down*.7f,pivot+d*2);Dot(pivot-d*2+down,.4f,Blue);Dot(pivot+d*2+down,.4f,Blue);var cm=pivot+down*.85f;Dot(cm,.12f,Yellow);Dot(pivot,.1f,White);Arrow(cm,cm+Vector3.down,Red);formula.text="질량중심이 지지점 아래\n기울면 중력이 복원 토크 생성\n\n양쪽 추를 벌림 → 관성 증가\n복원 효과와 느린 반응을 구분";values.text="기하학적 힘의 관계를 보여 주는 감쇠 진동 모형";}
  void CylinderInertia(double u){for(int i=0;i<2;i++){var c=new Vector3(-6.5f+i*4,.5f);Circle(c,1.3f,i==0?Blue:Teal);if(i==1)Circle(c,1.1f,Teal);double I=i==0?.5:1,angle=.5/I*u*u*3;Path(White,c,c+new Vector3((float)Math.Cos(angle),(float)Math.Sin(angle))*1.3f);Tag(c+new Vector3(-1.5f,-1.8f),i==0?"꽉 찬 원통":"얇은 고리",White,600);}formula.text="같은 m, R, τ\nIsolid = ½mR²\nIring = mR²\n\nα = τ/I\n고리는 각가속도가 절반";values.text="길이축 방향 단면 · 같은 토크의 실제 고정축 운동식";}
  void StudyLinks(double u){string[][] text={new[]{"역학 → 미분방정식","게임 물리 → 물리 기반 애니메이션","원리 → 구현 → 움직임 검산"},new[]{"Body / Shape / Constraint","ODE · Bullet 소스의 구조","충돌 검출 → 접촉 정보 → 반응"},new[]{"수치해석 · Scientific Computing","Euler → Runge–Kutta → 안정성","작은 예제의 오차를 비교"}};var list=text[Math.Min(2,shot.spokenStep)];for(int i=0;i<3;i++){var p=new Vector3(-7,2.5f-i*1.5f);Tag(p,list[i],i==(int)(u*3)%3?Yellow:White,1000);if(i<2)Arrow(p+new Vector3(.3f,-.6f),p+new Vector3(.3f,-1.1f),Teal);}formula.text="배우려는 장면을 정함\n→ 필요한 원리 확인\n→ 계산과 실제 동작 비교";values.text="자료의 순서를 연결하는 학습 지도";}
  void TotalSummary(double u){PointVelocity(u);formula.text="알짜힘 → 질량중심 운동\n토크 → 각운동량 변화\n접촉점 속도 = 이동 + 회전\n\n제약 해결 → 시간 적분\n→ 다음 위치와 자세";values.text="힘의 위치나 반발계수를 하나씩 바꾸고 결과를 비교";}
 }
